selector_to_html = {"a[href=\"pycmplot_python_api.html#Plot-in-panels\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Plot in panels<a class=\"headerlink\" href=\"#Plot-in-panels\" title=\"Link to this heading\">\uf0c1</a></h1><h2># Final Notes<a class=\"headerlink\" href=\"##-Final-Notes\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"cli.html#qq-plot-options\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">QQ plot options<a class=\"headerlink\" href=\"#qq-plot-options\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"api/io.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pycmplot.io<a class=\"headerlink\" href=\"#pycmplot-io\" title=\"Link to this heading\">\uf0c1</a></h1><p>Handles loading and pre-processing of summary statistics files.\nAuto-detects delimiters and resolves non-standard column names to the\ncanonical names used internally by pycmplot.</p>", "a[href=\"cli_tutorial.html#caching-and-warm-resume\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Caching and warm resume<a class=\"headerlink\" href=\"#caching-and-warm-resume\" title=\"Link to this heading\">\uf0c1</a></h2><p>Loading is the expensive step (I/O + trim + liftover + lead\nextraction).  Turn on caching and every re-run of the same\n<code class=\"docutils literal notranslate\"><span class=\"pre\">(files,</span> <span class=\"pre\">parameters)</span></code> combination completes in milliseconds:</p>", "a[href=\"installation.html#using-a-virtual-environment\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Using a virtual environment<a class=\"headerlink\" href=\"#using-a-virtual-environment\" title=\"Link to this heading\">\uf0c1</a></h2><p>If you cannot or prefer not to install into the system Python, use a virtual\nenvironment:</p>", "a[href=\"quickstart.html#mixed-genome-builds-with-liftover\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Mixed genome builds with liftover<a class=\"headerlink\" href=\"#mixed-genome-builds-with-liftover\" title=\"Link to this heading\">\uf0c1</a></h2><p>If your summary statistics were generated on different reference panels\n(hg18, hg19, or hg38), pycmplot can liftover hg18 and hg19 coordinates to\nhg38 before plotting. Supply the builds either through a <code class=\"docutils literal notranslate\"><span class=\"pre\">BUILD</span></code> column\nin the files or by passing <code class=\"docutils literal notranslate\"><span class=\"pre\">--build</span></code> (CLI) / <code class=\"docutils literal notranslate\"><span class=\"pre\">build_list=</span></code> (API):</p>", "a[href=\"cli.html#example-commands\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Example commands<a class=\"headerlink\" href=\"#example-commands\" title=\"Link to this heading\">\uf0c1</a></h2><h3>Single-trait linear Manhattan plot<a class=\"headerlink\" href=\"#single-trait-linear-manhattan-plot\" title=\"Link to this heading\">\uf0c1</a></h3>", "a[href=\"cli_tutorial.html#multi-panel-canvas\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-panel canvas<a class=\"headerlink\" href=\"#multi-panel-canvas\" title=\"Link to this heading\">\uf0c1</a></h2><p>Multi-panel canvases \u2014 where each panel is its own stacked linear (or\ncircular) sub-plot \u2014 are a <strong>Python API</strong> feature.  The CLI produces\none figure per invocation; if you need multiple sumstats groups laid\nout on the same canvas (e.g. Hb on top, MCV on bottom, sharing a\ntitle and legend), use the notebook workflow described in\n<a class=\"reference internal\" href=\"python_api_tutorial.html#python-api-tutorial\"><span class=\"std std-ref\">Python API Tutorial</span></a> under \u201cMulti-panel canvas\u201d.  Every cache\nfile, hits overlay, per-locus colour, and category legend is\n<em>group-scoped</em> under both interfaces, so two panels with different\nsumstats never clobber each other\u2019s artefacts.</p>", "a[href=\"installation.html#requirements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Requirements<a class=\"headerlink\" href=\"#requirements\" title=\"Link to this heading\">\uf0c1</a></h2><p>pycmplot requires <strong>Python 3.9 or later</strong>. The following packages are installed\nautomatically as dependencies:</p>", "a[href=\"cli_tutorial.html#automatic-gene-annotation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Automatic gene annotation<a class=\"headerlink\" href=\"#automatic-gene-annotation\" title=\"Link to this heading\">\uf0c1</a></h2><p>Add <code class=\"docutils literal notranslate\"><span class=\"pre\">--annotate</span> <span class=\"pre\">GENE</span></code> to label each lead SNP with its nearest\ngene, and optionally <code class=\"docutils literal notranslate\"><span class=\"pre\">--label_col</span> <span class=\"pre\">top_gene</span></code> to control which\ncolumn from the hits table is used as the label:</p>", "a[href=\"#indices-and-tables\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Indices and tables<a class=\"headerlink\" href=\"#indices-and-tables\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"cli.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Command-Line Interface<a class=\"headerlink\" href=\"#command-line-interface\" title=\"Link to this heading\">\uf0c1</a></h1><p>pycmplot exposes a full command-line interface that mirrors the Python API.\nAfter installation, the <code class=\"docutils literal notranslate\"><span class=\"pre\">pycmplot</span></code> command is available in your PATH.</p>", "a[href=\"api/stats.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pycmplot.stats<a class=\"headerlink\" href=\"#pycmplot-stats\" title=\"Link to this heading\">\uf0c1</a></h1><p>Statistical utilities for identifying significant loci from GWAS summary\nstatistics. Provides lead-SNP extraction using a LD-pruning-free distance\nclumping approach, and helpers for selecting SNPs to highlight in the plot.</p>", "a[href=\"#pycmplot\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pycmplot<a class=\"headerlink\" href=\"#pycmplot\" title=\"Link to this heading\">\uf0c1</a></h1><p><strong>pycmplot</strong> is a Python package for generating multi-track circular and linear\nManhattan plots from GWAS summary statistics. It accepts any number of per-variant\nsummary statistic files \u2014 GWAS, selection scans (iHS, FST, XP-EHH), or any\ncolumn-delimited p-value table \u2014 and produces publication-ready Manhattan plots\nwith automatic gene annotation, lead-SNP extraction, and optional hg19 \u2192 hg38\ncoordinate liftover.</p>", "a[href=\"quickstart.html#command-line\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Command line<a class=\"headerlink\" href=\"#command-line\" title=\"Link to this heading\">\uf0c1</a></h2><p>Most users will use the CLI. The typical invocation for a multi-track plot is:</p>", "a[href=\"installation.html#from-github-development-version\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">From GitHub (development version)<a class=\"headerlink\" href=\"#from-github-development-version\" title=\"Link to this heading\">\uf0c1</a></h2><p>If your system Python is externally managed (common on Ubuntu 22.04+):</p>", "a[href=\"cli_tutorial.html#setup-a-synthetic-dataset\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Setup: a synthetic dataset<a class=\"headerlink\" href=\"#setup-a-synthetic-dataset\" title=\"Link to this heading\">\uf0c1</a></h2><p>Every CLI invocation below assumes six synthetic sumstats files on\ndisk (<code class=\"docutils literal notranslate\"><span class=\"pre\">trait{1..6}.tsv.gz</span></code>). Download the python script used for benchmark\n<a class=\"reference external\" href=\"https://github.com/esohkevin/pycmplot/blob/main/benchmark/generate_sumstats.py\">here</a> and run it as shown below.</p><p>The code below generates six sumstats, <code class=\"docutils literal notranslate\"><span class=\"pre\">triat1</span></code> to <code class=\"docutils literal notranslate\"><span class=\"pre\">trait6</span></code>, each containing\n1 million SNPs. Traits 1 to 3 are in hg19 coordinate while traits 4 to 6 are\nin hg38 coordinate. All the files are gzipped and saved in the folder <code class=\"docutils literal notranslate\"><span class=\"pre\">data</span></code>.\nThe <code class=\"docutils literal notranslate\"><span class=\"pre\">--targets</span> <span class=\"pre\">auto</span></code> option injects 6 significant loci on chr3, chr6, chr11,\nchr13, chr18, and chr20 in all sumstats, 2 significant loci specific to hg19 sumstats\n(in chr2 and chr15) and 2 significant loci specific to hg38 sumstats (in chr12 and chr16).\nThese are actuall <strong>body height</strong> significant loci pulled from <a class=\"reference external\" href=\"https://www.ebi.ac.uk/gwas/efotraits/OBA_VT0001253\">GWAS Catalog</a>.</p>", "a[href=\"api/liftover.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pycmplot.liftover<a class=\"headerlink\" href=\"#pycmplot-liftover\" title=\"Link to this heading\">\uf0c1</a></h1><p>Lazy hg18 \u2192 hg38 and hg19 \u2192 hg38 coordinate conversion powered by\n<a class=\"reference external\" href=\"https://github.com/konstantint/pyliftover\">pyliftover</a>.\nConversion is triggered only when a genome-build column is detected (or\nexplicitly named via <code class=\"docutils literal notranslate\"><span class=\"pre\">--build_column</span></code>), and only for rows annotated as\n<code class=\"docutils literal notranslate\"><span class=\"pre\">hg18</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">hg19</span></code>. All other rows are passed through unchanged.</p>", "a[href=\"cli_tutorial.html#per-locus-highlight-colours\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Per-locus highlight colours<a class=\"headerlink\" href=\"#per-locus-highlight-colours\" title=\"Link to this heading\">\uf0c1</a></h2><p>Set the <code class=\"docutils literal notranslate\"><span class=\"pre\">highlight_color</span></code> column on any row to a matplotlib-parseable\ncolour (name, <code class=\"docutils literal notranslate\"><span class=\"pre\">#rrggbb</span></code> hex, or an <code class=\"docutils literal notranslate\"><span class=\"pre\">(r,</span> <span class=\"pre\">g,</span> <span class=\"pre\">b)</span></code> tuple):</p>", "a[href=\"contributing.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Contributing<a class=\"headerlink\" href=\"#contributing\" title=\"Link to this heading\">\uf0c1</a></h1><p>Bug reports, feature requests, and pull requests are welcome on the\n<a class=\"reference external\" href=\"https://github.com/esohkevin/pycmplot\">GitHub repository</a>.</p>", "a[href=\"cli_tutorial.html#troubleshooting\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Troubleshooting<a class=\"headerlink\" href=\"#troubleshooting\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"api/plotting.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pycmplot.plotting<a class=\"headerlink\" href=\"#pycmplot-plotting\" title=\"Link to this heading\">\uf0c1</a></h1><p>The plotting subpackage contains three modules: one for linear (stacked)\nManhattan plots, one for circular (Circos-style) Manhattan plots, and one\nfor QQ plots.</p>", "a[href=\"cli_tutorial.html#circular-circos-plots\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Circular (Circos) plots<a class=\"headerlink\" href=\"#circular-circos-plots\" title=\"Link to this heading\">\uf0c1</a></h2><p>Every command in <a class=\"reference internal\" href=\"#cli-tut-linear\"><span class=\"std std-ref\">Linear Manhattan plots</span></a> above has an inline\n<code class=\"docutils literal notranslate\"><span class=\"pre\">Circular</span></code> tab that swaps <code class=\"docutils literal notranslate\"><span class=\"pre\">--mode</span> <span class=\"pre\">cm</span></code> in.  Because the two\nplotting modes share every other flag on the CLI (except\n<code class=\"docutils literal notranslate\"><span class=\"pre\">--track_heights</span></code>, which is linear-only), keeping the examples in\ntabs \u2014 rather than a separate section \u2014 lets you compare the two\nlayouts side-by-side at each demonstration.</p><p>Click any \u201cCircular\u201d tab in the linear section above and every other\ntab-set on this page snaps to Circular too (sync group <code class=\"docutils literal notranslate\"><span class=\"pre\">circular</span></code>),\nso a Circos-first reader can flip once and follow along without\nclicking tab-by-tab.</p>", "a[href=\"license.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">License<a class=\"headerlink\" href=\"#license\" title=\"Link to this heading\">\uf0c1</a></h1><p>pycmplot is distributed under the terms of its open-source license.\nSee the <a class=\"reference external\" href=\"https://github.com/esohkevin/pycmplot/blob/main/LICENSE\">LICENSE</a>\nfile in the GitHub repository for the full text.</p>", "a[href=\"api/resources.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pycmplot.resources<a class=\"headerlink\" href=\"#pycmplot-resources\" title=\"Link to this heading\">\uf0c1</a></h1><p>Centralised configuration for external reference files (liftover chain,\ngene-info TSVs).  Paths are resolved from environment variables or the\nbundled <code class=\"docutils literal notranslate\"><span class=\"pre\">pycmplot/data/</span></code> directory; individual paths can be overridden\nby passing a custom <a class=\"reference internal\" href=\"#pycmplot.resources.ResourceConfig\" title=\"pycmplot.resources.ResourceConfig\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">ResourceConfig</span></code></a> instance\nto any function that accepts a <em>resources</em> argument.</p>", "a[href=\"python_api_tutorial.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Python API Tutorial<a class=\"headerlink\" href=\"#python-api-notebook\" title=\"Link to this heading\">\uf0c1</a></h1><p>The interactive tutorial below demonstrates the full Python API using real\nsummary statistics data. It covers data loading, single- and multi-track\nlinear Manhattan plots, circular Manhattan plots, liftover, and the hits\nsummary table.</p>", "a[href=\"quickstart.html#next-steps\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Next steps<a class=\"headerlink\" href=\"#next-steps\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"quickstart.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Quickstart<a class=\"headerlink\" href=\"#quickstart\" title=\"Link to this heading\">\uf0c1</a></h1><p>This page walks through the most common workflows in a few lines each.\nFor a detailed walkthrough with real data, see <a class=\"reference internal\" href=\"python_api_tutorial.html#python-api-tutorial\"><span class=\"std std-ref\">Python API Tutorial</span></a>.</p>", "a[href=\"#key-features\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Key features<a class=\"headerlink\" href=\"#key-features\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"quickstart.html#input-file-format\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Input file format<a class=\"headerlink\" href=\"#input-file-format\" title=\"Link to this heading\">\uf0c1</a></h2><p>pycmplot accepts any whitespace- or comma-delimited summary statistics file,\nincluding gzip-compressed (<code class=\"docutils literal notranslate\"><span class=\"pre\">.gz</span></code>) files. Required columns (auto-detected from\ncommon names) are:</p>", "a[href=\"api/annotation.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pycmplot.annotation<a class=\"headerlink\" href=\"#pycmplot-annotation\" title=\"Link to this heading\">\uf0c1</a></h1><p>Nearest-gene annotation for lead SNPs and generation of the hits summary\ntable. Annotations are based on physical proximity to gene boundaries using\na bundled gene reference, with optional biotype weighting.</p>", "a[href=\"pycmplot_python_api.html#Example-plotting\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Example plotting<a class=\"headerlink\" href=\"#Example-plotting\" title=\"Link to this heading\">\uf0c1</a></h1><h2>Important notes<a class=\"headerlink\" href=\"#Important-notes\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"pycmplot_python_api.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Python API for the pycmplot package<a class=\"headerlink\" href=\"#Python-API-for-the-pycmplot-package\" title=\"Link to this heading\">\uf0c1</a></h1><h2>Installation<a class=\"headerlink\" href=\"#Installation\" title=\"Link to this heading\">\uf0c1</a></h2><p>Follow instructions in <a class=\"reference external\" href=\"https://pypi.org/project/pycmplot/\">https://pypi.org/project/pycmplot/</a></p>", "a[href=\"cli_tutorial.html#the-hits-overlay-tsv\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">The hits overlay TSV<a class=\"headerlink\" href=\"#the-hits-overlay-tsv\" title=\"Link to this heading\">\uf0c1</a></h2><p>When caching is enabled, the loader writes the hits table to a\ngroup-scoped TSV that <strong>you\u2019re expected to hand-edit</strong>.  The path is:</p>", "a[href=\"cli_tutorial.html#mixed-genome-builds\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Mixed genome builds<a class=\"headerlink\" href=\"#mixed-genome-builds\" title=\"Link to this heading\">\uf0c1</a></h2><p>If your files were generated on different reference panels, pycmplot\ncan lift over hg18 and hg19 coordinates to hg38 before plotting.\nSupply the per-file builds via a comma-separated <code class=\"docutils literal notranslate\"><span class=\"pre\">--build</span></code> list in\nthe same order as <code class=\"docutils literal notranslate\"><span class=\"pre\">--sum_stats</span></code>:</p>", "a[href=\"cli.html#column-auto-detection-options\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Column auto-detection options<a class=\"headerlink\" href=\"#column-auto-detection-options\" title=\"Link to this heading\">\uf0c1</a></h2><p>pycmplot infers column names automatically. Use these flags only if your\ncolumn names fall outside the recognised defaults.</p>", "a[href=\"cli_tutorial.html#qq-plots-and-compute-pvals\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">QQ plots and <code class=\"docutils literal notranslate\"><span class=\"pre\">compute_pvals</span></code><a class=\"headerlink\" href=\"#qq-plots-and-compute-pvals\" title=\"Link to this heading\">\uf0c1</a></h2><p>The loader normally skips materialising the full sorted p-value\narray (~80 MB per track at 10 M variants) because most users never\ndraw a QQ plot.  The CLI <code class=\"docutils literal notranslate\"><span class=\"pre\">--qq_plot</span></code> flag turns that computation on\nautomatically \u2014 you never need to think about the underlying\n<code class=\"docutils literal notranslate\"><span class=\"pre\">compute_pvals</span></code> parameter:</p>", "a[href=\"cli_tutorial.html#highlighting\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Highlighting<a class=\"headerlink\" href=\"#highlighting\" title=\"Link to this heading\">\uf0c1</a></h2><p>Add <code class=\"docutils literal notranslate\"><span class=\"pre\">--highlight</span></code> to colour signals above a threshold, and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">--signif_line</span></code> to draw a horizontal cut-off line at that threshold:</p>", "a[href=\"cli.html#input-output-options\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Input / output options<a class=\"headerlink\" href=\"#input-output-options\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"cli_tutorial.html#the-cli-mental-model\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">The CLI mental model<a class=\"headerlink\" href=\"#the-cli-mental-model\" title=\"Link to this heading\">\uf0c1</a></h2><p>Every <code class=\"docutils literal notranslate\"><span class=\"pre\">pycmplot</span></code> invocation performs the same three steps internally\n\u2014 column resolution, data loading (+ optional liftover, lead extraction,\nhits-table construction), and rendering.  From the CLI you don\u2019t have\nto think about them separately: one command runs the whole pipeline\nand writes the output image(s) plus a locus summary TSV.</p><p><strong>The canonical minimum invocation is:</strong></p>", "a[href=\"installation.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Installation<a class=\"headerlink\" href=\"#installation\" title=\"Link to this heading\">\uf0c1</a></h1><h2>Requirements<a class=\"headerlink\" href=\"#requirements\" title=\"Link to this heading\">\uf0c1</a></h2><p>pycmplot requires <strong>Python 3.9 or later</strong>. The following packages are installed\nautomatically as dependencies:</p>", "a[href=\"quickstart.html#python-api\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Python API<a class=\"headerlink\" href=\"#python-api\" title=\"Link to this heading\">\uf0c1</a></h2><p>The Python API exposes the same pipeline as the CLI, with three explicit\nsteps: (1) resolve per-file column names, (2) load and pre-process the\nsummary statistics, (3) render the plot. The rendering functions take the\n<code class=\"docutils literal notranslate\"><span class=\"pre\">sumstats_loaded</span></code> dictionary produced in step 2.</p>", "a[href=\"cli_tutorial.html#per-locus-categories-and-the-custom-legend\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Per-locus categories and the custom legend<a class=\"headerlink\" href=\"#per-locus-categories-and-the-custom-legend\" title=\"Link to this heading\">\uf0c1</a></h2><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">category</span></code> column lets you group loci in the legend:</p>", "a[href=\"changelog.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Changelog<a class=\"headerlink\" href=\"#changelog\" title=\"Link to this heading\">\uf0c1</a></h1><p>All notable changes to <strong>pycmplot</strong> are documented here.</p><p>The format is based on <a class=\"reference external\" href=\"https://keepachangelog.com/en/1.0.0/\">Keep a Changelog</a>\nand this project adheres to <a class=\"reference external\" href=\"https://semver.org/\">Semantic Versioning</a>.</p>", "a[href=\"installation.html#from-pypi-recommended\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">From PyPI (recommended)<a class=\"headerlink\" href=\"#from-pypi-recommended\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"cli_tutorial.html#cli-equivalents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">CLI equivalents<a class=\"headerlink\" href=\"#cli-equivalents\" title=\"Link to this heading\">\uf0c1</a></h2><p>Everything above has a CLI equivalent.  A representative one-liner:</p>", "a[href=\"cli_tutorial.html#next-steps\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Next steps<a class=\"headerlink\" href=\"#next-steps\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"cli.html#plotting-behaviour-options\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Plotting behaviour options<a class=\"headerlink\" href=\"#plotting-behaviour-options\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"installation.html#verify-the-installation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Verify the installation<a class=\"headerlink\" href=\"#verify-the-installation\" title=\"Link to this heading\">\uf0c1</a></h2><p>A successful installation prints the full help message with all command-line\noptions.</p>", "a[href=\"api/constants.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pycmplot.constants<a class=\"headerlink\" href=\"#pycmplot-constants\" title=\"Link to this heading\">\uf0c1</a></h1><p>Genome-level constants shared across pycmplot modules: GRCh38 chromosome\nlengths, gene biotype priority weights, and standard chromosome ordering.</p>", "a[href=\"api/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">API Reference<a class=\"headerlink\" href=\"#api-reference\" title=\"Link to this heading\">\uf0c1</a></h1><p>This section documents every public function and class exposed by pycmplot.\nAll symbols listed here are importable directly from the top-level package\n(<code class=\"docutils literal notranslate\"><span class=\"pre\">from</span> <span class=\"pre\">pycmplot</span> <span class=\"pre\">import</span> <span class=\"pre\">...</span></code>) unless noted otherwise.</p>", "a[href=\"cli_tutorial.html#gui-editor-for-the-hits-overlay\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">GUI editor for the hits overlay<a class=\"headerlink\" href=\"#gui-editor-for-the-hits-overlay\" title=\"Link to this heading\">\uf0c1</a></h2><p>If hand-editing the <code class=\"docutils literal notranslate\"><span class=\"pre\">hits.&lt;group&gt;.tsv</span></code> in a text editor feels\nawkward \u2014 especially picking colours by typing hex codes \u2014 pycmplot\nships an optional browser-based editor.  Install the extra and launch\nit against your cache directory:</p>", "a[href=\"cli_tutorial.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">CLI Tutorial<a class=\"headerlink\" href=\"#cli-tutorial\" title=\"Link to this heading\">\uf0c1</a></h1><p>This tutorial is an end-to-end walkthrough of every user-facing feature\nin <strong>pycmplot</strong> from the <em>command line</em>, working from the same synthetic\ndataset throughout so that every command is directly copy-pasteable.\nIt\u2019s longer and more granular than <a class=\"reference internal\" href=\"quickstart.html#quickstart\"><span class=\"std std-ref\">Quickstart</span></a> \u2014 read the\nquickstart first if you just want to see the shape of the CLI in a page.</p><p>Looking for the equivalent Python-API walkthrough?  See\n<a class=\"reference internal\" href=\"python_api_tutorial.html#python-api-tutorial\"><span class=\"std std-ref\">Python API Tutorial</span></a> \u2014 it covers the same features using the\n<code class=\"docutils literal notranslate\"><span class=\"pre\">pcm.prep</span></code> / <code class=\"docutils literal notranslate\"><span class=\"pre\">pcm.load</span></code> / <code class=\"docutils literal notranslate\"><span class=\"pre\">pcm.linear</span></code> / <code class=\"docutils literal notranslate\"><span class=\"pre\">pcm.circular</span></code>\nfunctions in a runnable Jupyter notebook.</p>", "a[href=\"cli_tutorial.html#linear-manhattan-plots\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Linear Manhattan plots<a class=\"headerlink\" href=\"#linear-manhattan-plots\" title=\"Link to this heading\">\uf0c1</a></h2><h3>Single-track:<a class=\"headerlink\" href=\"#single-track\" title=\"Link to this heading\">\uf0c1</a></h3><p><strong>Highlight, and add plot title and significant/suggestive lines to the base above</strong></p><p>pycmplot defaults to <code class=\"docutils literal notranslate\"><span class=\"pre\">--mode</span> <span class=\"pre\">lm</span></code> (linear Manhattan).  Add\n<code class=\"docutils literal notranslate\"><span class=\"pre\">--mode</span> <span class=\"pre\">cm</span></code> to switch to the Circos-style circular layout \u2014 every\nother flag stays the same.  Use <code class=\"docutils literal notranslate\"><span class=\"pre\">pycmplot</span> <span class=\"pre\">-h</span></code> for the full\nmode-specific option list.</p>", "a[href=\"pycmplot_python_api.html#Multi-panel-Circular-Manhattan-Plotting\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-panel Circular Manhattan Plotting<a class=\"headerlink\" href=\"#Multi-panel-Circular-Manhattan-Plotting\" title=\"Link to this heading\">\uf0c1</a></h1><h2>Specify groups of sumstats to load and plot in different panels<a class=\"headerlink\" href=\"#Specify-groups-of-sumstats-to-load-and-plot-in-different-panels\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"#contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Contents<a class=\"headerlink\" href=\"#contents\" title=\"Link to this heading\">\uf0c1</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: true, theme: 'light-border',

            });
        };
    };
    console.log("tippy tips loaded!");
};
